import os

compositions = ['NaN', 'SrN', 'AlN', 'GaN', 'InN', 'Si3N4', 'Ge3N4', 'TiN', 'ZrN', 'HfN', 'VN', 'NbN', 'TaN', 'CrN', 'MoN', 'WN', 'Mn3N2', 'Fe4N', 'Co3N', 'Ni3N', 'Cu3N', 'ScN', 'YN', 'LaN', 'CeN', 'BN']

filtered_data = []
base_path = 'polymorph_data'

for comp in compositions:
    filepath = os.path.join(base_path, f'{comp}_polymorphs.json')
    try:
        with open(filepath, 'r') as f:
            polymorphs = json.load(f)
        for p in polymorphs:
            p['source_composition'] = comp
            filtered_data.append(p)
    except:
        pass
